CREATE TABLE public.lupg_phq_participants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kelompok_id uuid NOT NULL REFERENCES public.lookup_values(id) ON DELETE RESTRICT, name text NOT NULL CHECK (NULLIF(btrim(name), '') IS NOT NULL), category_code text NOT NULL CHECK (category_code IN ('ACR','APR','AR','GPN_A','GPN_B')), gender text NOT NULL CHECK (gender IN ('L','P')), status_active boolean NOT NULL DEFAULT true, birth_date date, highest_juz smallint CHECK (highest_juz IS NULL OR highest_juz BETWEEN 1 AND 30), highest_surat text, highest_ayat_from integer, highest_ayat_to integer, highest_juz_mastery_percent numeric(5,2) CHECK (highest_juz_mastery_percent IS NULL OR highest_juz_mastery_percent BETWEEN 0 AND 100), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT lupg_phq_participants_highest_ayat_range_check CHECK ((highest_ayat_from IS NULL AND highest_ayat_to IS NULL) OR (highest_ayat_from IS NOT NULL AND highest_ayat_to IS NOT NULL AND highest_ayat_from > 0 AND highest_ayat_from <= highest_ayat_to)));
CREATE TABLE public.lupg_phq_meetings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kelompok_id uuid NOT NULL REFERENCES public.lookup_values(id) ON DELETE RESTRICT, activity_date date NOT NULL, month date GENERATED ALWAYS AS (date_trunc('month', activity_date::timestamp)::date) STORED, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.lupg_phq_progress (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), participant_id uuid NOT NULL REFERENCES public.lupg_phq_participants(id) ON DELETE RESTRICT, meeting_id uuid NOT NULL REFERENCES public.lupg_phq_meetings(id) ON DELETE CASCADE, score numeric(5,2) NOT NULL CHECK (score BETWEEN 0 AND 100), juz smallint CHECK (juz IS NULL OR juz BETWEEN 1 AND 30), surat text, ayat_from integer, ayat_to integer, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (participant_id, meeting_id), CONSTRAINT lupg_phq_progress_ayat_range_check CHECK ((ayat_from IS NULL AND ayat_to IS NULL) OR (ayat_from IS NOT NULL AND ayat_to IS NOT NULL AND ayat_from > 0 AND ayat_from <= ayat_to)));
CREATE TABLE public.lupg_phq_attendance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), participant_id uuid NOT NULL REFERENCES public.lupg_phq_participants(id) ON DELETE RESTRICT, meeting_id uuid NOT NULL REFERENCES public.lupg_phq_meetings(id) ON DELETE CASCADE, status text NOT NULL CHECK (status IN ('hadir','izin','sakit','alpa')), notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (participant_id, meeting_id));
CREATE TABLE public.lupg_phq_monthly_notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kelompok_id uuid NOT NULL REFERENCES public.lookup_values(id) ON DELETE RESTRICT, month date NOT NULL CHECK (extract(day FROM month) = 1), notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (kelompok_id, month));
CREATE TABLE public.lupg_intensif_activities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), program_code text NOT NULL CHECK (program_code IN ('APR_INTENSIF','AR_INTENSIF')), kelompok_id uuid NOT NULL REFERENCES public.lookup_values(id) ON DELETE RESTRICT, activity_date date NOT NULL, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (program_code, activity_date, kelompok_id));
CREATE TABLE public.lupg_intensif_attendance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), activity_id uuid NOT NULL REFERENCES public.lupg_intensif_activities(id) ON DELETE CASCADE, participant_id uuid NOT NULL REFERENCES public.participants(id) ON DELETE RESTRICT, participant_name text NOT NULL, participant_gender text CHECK (participant_gender IS NULL OR participant_gender IN ('L','P')), participant_category_code text NOT NULL CHECK (participant_category_code IN ('APR','AR')), status text NOT NULL CHECK (status IN ('hadir','izin','sakit','alpa')), notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (activity_id, participant_id));
CREATE INDEX lupg_phq_participants_kelompok_id_idx ON public.lupg_phq_participants (kelompok_id); CREATE INDEX lupg_phq_meetings_kelompok_activity_date_idx ON public.lupg_phq_meetings (kelompok_id, activity_date); CREATE INDEX lupg_phq_progress_meeting_id_idx ON public.lupg_phq_progress (meeting_id); CREATE INDEX lupg_phq_attendance_meeting_id_idx ON public.lupg_phq_attendance (meeting_id); CREATE INDEX lupg_intensif_activities_kelompok_activity_date_idx ON public.lupg_intensif_activities (kelompok_id, activity_date); CREATE INDEX lupg_intensif_attendance_participant_id_idx ON public.lupg_intensif_attendance (participant_id);
CREATE OR REPLACE FUNCTION public.fn_lupg_phq_limit_meetings() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$ BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(NEW.kelompok_id::text || ':' || date_trunc('month', NEW.activity_date::timestamp)::date::text, 0)); IF (SELECT count(*) FROM public.lupg_phq_meetings m WHERE m.kelompok_id = NEW.kelompok_id AND m.month = date_trunc('month', NEW.activity_date::timestamp)::date AND (TG_OP = 'INSERT' OR m.id <> NEW.id)) >= 4 THEN RAISE EXCEPTION 'PHQ hanya dapat memiliki maksimal empat pertemuan per kelompok per bulan'; END IF; RETURN NEW; END; $$;
CREATE OR REPLACE FUNCTION public.fn_lupg_phq_validate_scope() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.lupg_phq_participants p JOIN public.lupg_phq_meetings m ON m.id = NEW.meeting_id WHERE p.id = NEW.participant_id AND p.kelompok_id = m.kelompok_id) THEN RAISE EXCEPTION 'Peserta PHQ harus berasal dari kelompok pertemuan yang sama'; END IF; RETURN NEW; END; $$;
CREATE OR REPLACE FUNCTION public.fn_lupg_intensif_validate_attendance() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$ DECLARE v_name text; v_gender text; v_category text; v_program text; BEGIN SELECT p.name, p.gender, c.value, a.program_code INTO v_name, v_gender, v_category, v_program FROM public.lupg_intensif_activities a JOIN public.participants p ON p.id = NEW.participant_id JOIN public.lookup_values c ON c.id = p.category_id WHERE a.id = NEW.activity_id AND p.status_active AND p.group_id = a.kelompok_id; IF NOT FOUND OR (v_program = 'APR_INTENSIF' AND v_category <> 'APR') OR (v_program = 'AR_INTENSIF' AND v_category <> 'AR') THEN RAISE EXCEPTION 'Peserta Intensif harus aktif, sesuai kelompok, dan sesuai kategori program'; END IF; NEW.participant_name := v_name; NEW.participant_gender := v_gender; NEW.participant_category_code := v_category; RETURN NEW; END; $$;
CREATE TRIGGER tg_lupg_phq_limit_meetings BEFORE INSERT OR UPDATE OF kelompok_id, activity_date ON public.lupg_phq_meetings FOR EACH ROW EXECUTE FUNCTION public.fn_lupg_phq_limit_meetings(); CREATE TRIGGER tg_lupg_phq_progress_validate_scope BEFORE INSERT OR UPDATE OF participant_id, meeting_id ON public.lupg_phq_progress FOR EACH ROW EXECUTE FUNCTION public.fn_lupg_phq_validate_scope(); CREATE TRIGGER tg_lupg_phq_attendance_validate_scope BEFORE INSERT OR UPDATE OF participant_id, meeting_id ON public.lupg_phq_attendance FOR EACH ROW EXECUTE FUNCTION public.fn_lupg_phq_validate_scope(); CREATE TRIGGER tg_lupg_intensif_attendance_validate BEFORE INSERT OR UPDATE OF activity_id, participant_id ON public.lupg_intensif_attendance FOR EACH ROW EXECUTE FUNCTION public.fn_lupg_intensif_validate_attendance();
ALTER TABLE public.lupg_phq_participants ENABLE ROW LEVEL SECURITY; ALTER TABLE public.lupg_phq_meetings ENABLE ROW LEVEL SECURITY; ALTER TABLE public.lupg_phq_progress ENABLE ROW LEVEL SECURITY; ALTER TABLE public.lupg_phq_attendance ENABLE ROW LEVEL SECURITY; ALTER TABLE public.lupg_phq_monthly_notes ENABLE ROW LEVEL SECURITY; ALTER TABLE public.lupg_intensif_activities ENABLE ROW LEVEL SECURITY; ALTER TABLE public.lupg_intensif_attendance ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t text; action text; BEGIN FOREACH t IN ARRAY ARRAY['lupg_phq_participants','lupg_phq_meetings','lupg_phq_monthly_notes','lupg_intensif_activities'] LOOP FOREACH action IN ARRAY ARRAY['select','insert','update','delete'] LOOP EXECUTE format('CREATE POLICY %I ON public.%I FOR %s TO authenticated %s', t || '_' || action, t, upper(action), CASE action WHEN 'select' THEN 'USING (public.user_role() IN (''super_admin'',''admin'') OR (public.user_role() = ''mt'' AND kelompok_id = public.user_kelompok_id()))' WHEN 'insert' THEN 'WITH CHECK (public.user_role() IN (''super_admin'',''admin'') OR (public.user_role() = ''mt'' AND kelompok_id = public.user_kelompok_id()))' WHEN 'update' THEN 'USING (public.user_role() IN (''super_admin'',''admin'') OR (public.user_role() = ''mt'' AND kelompok_id = public.user_kelompok_id())) WITH CHECK (public.user_role() IN (''super_admin'',''admin'') OR (public.user_role() = ''mt'' AND kelompok_id = public.user_kelompok_id()))' ELSE 'USING (public.user_role() IN (''super_admin'',''admin'') OR (public.user_role() = ''mt'' AND kelompok_id = public.user_kelompok_id()))' END); END LOOP; END LOOP; FOREACH t IN ARRAY ARRAY['lupg_phq_progress','lupg_phq_attendance','lupg_intensif_attendance'] LOOP FOREACH action IN ARRAY ARRAY['select','insert','update','delete'] LOOP EXECUTE format('CREATE POLICY %I ON public.%I FOR %s TO authenticated %s', t || '_' || action, t, upper(action), CASE WHEN t = 'lupg_intensif_attendance' THEN CASE action WHEN 'select' THEN 'USING (EXISTS (SELECT 1 FROM public.lupg_intensif_activities a WHERE a.id = activity_id AND (public.user_role() IN (''super_admin'',''admin'') OR (public.user_role() = ''mt'' AND a.kelompok_id = public.user_kelompok_id()))))' WHEN 'insert' THEN 'WITH CHECK (EXISTS (SELECT 1 FROM public.lupg_intensif_activities a WHERE a.id = activity_id AND (public.user_role() IN (''super_admin'',''admin'') OR (public.user_role() = ''mt'' AND a.kelompok_id = public.user_kelompok_id()))))' WHEN 'update' THEN 'USING (EXISTS (SELECT 1 FROM public.lupg_intensif_activities a WHERE a.id = activity_id AND (public.user_role() IN (''super_admin'',''admin'') OR (public.user_role() = ''mt'' AND a.kelompok_id = public.user_kelompok_id())))) WITH CHECK (EXISTS (SELECT 1 FROM public.lupg_intensif_activities a WHERE a.id = activity_id AND (public.user_role() IN (''super_admin'',''admin'') OR (public.user_role() = ''mt'' AND a.kelompok_id = public.user_kelompok_id()))))' ELSE 'USING (EXISTS (SELECT 1 FROM public.lupg_intensif_activities a WHERE a.id = activity_id AND (public.user_role() IN (''super_admin'',''admin'') OR (public.user_role() = ''mt'' AND a.kelompok_id = public.user_kelompok_id()))))' END ELSE CASE action WHEN 'select' THEN 'USING (EXISTS (SELECT 1 FROM public.lupg_phq_meetings m WHERE m.id = meeting_id AND (public.user_role() IN (''super_admin'',''admin'') OR (public.user_role() = ''mt'' AND m.kelompok_id = public.user_kelompok_id()))))' WHEN 'insert' THEN 'WITH CHECK (EXISTS (SELECT 1 FROM public.lupg_phq_meetings m WHERE m.id = meeting_id AND (public.user_role() IN (''super_admin'',''admin'') OR (public.user_role() = ''mt'' AND m.kelompok_id = public.user_kelompok_id()))))' WHEN 'update' THEN 'USING (EXISTS (SELECT 1 FROM public.lupg_phq_meetings m WHERE m.id = meeting_id AND (public.user_role() IN (''super_admin'',''admin'') OR (public.user_role() = ''mt'' AND m.kelompok_id = public.user_kelompok_id())))) WITH CHECK (EXISTS (SELECT 1 FROM public.lupg_phq_meetings m WHERE m.id = meeting_id AND (public.user_role() IN (''super_admin'',''admin'') OR (public.user_role() = ''mt'' AND m.kelompok_id = public.user_kelompok_id()))))' ELSE 'USING (EXISTS (SELECT 1 FROM public.lupg_phq_meetings m WHERE m.id = meeting_id AND (public.user_role() IN (''super_admin'',''admin'') OR (public.user_role() = ''mt'' AND m.kelompok_id = public.user_kelompok_id()))))' END END); END LOOP; END LOOP; END $$;
REVOKE ALL ON TABLE public.lupg_phq_participants, public.lupg_phq_meetings, public.lupg_phq_progress, public.lupg_phq_attendance, public.lupg_phq_monthly_notes, public.lupg_intensif_activities, public.lupg_intensif_attendance FROM PUBLIC, anon; GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.lupg_phq_participants, public.lupg_phq_meetings, public.lupg_phq_progress, public.lupg_phq_attendance, public.lupg_phq_monthly_notes, public.lupg_intensif_activities, public.lupg_intensif_attendance TO authenticated; REVOKE ALL ON FUNCTION public.fn_lupg_phq_limit_meetings(), public.fn_lupg_phq_validate_scope(), public.fn_lupg_intensif_validate_attendance() FROM PUBLIC, anon, authenticated;
CREATE VIEW public.lupg_phq_summary WITH (security_invoker = true) AS SELECT m.month, m.kelompok_id, count(*)::integer AS meeting_count, (SELECT count(DISTINCT p.participant_id)::integer FROM public.lupg_phq_progress p JOIN public.lupg_phq_meetings pm ON pm.id = p.meeting_id WHERE pm.month = m.month AND pm.kelompok_id = m.kelompok_id) AS progressed_participant_count, (SELECT count(DISTINCT a.participant_id) FILTER (WHERE a.status = 'hadir')::integer FROM public.lupg_phq_attendance a JOIN public.lupg_phq_meetings am ON am.id = a.meeting_id WHERE am.month = m.month AND am.kelompok_id = m.kelompok_id) AS present_participant_count, (SELECT avg(p.score) FROM public.lupg_phq_progress p JOIN public.lupg_phq_meetings pm ON pm.id = p.meeting_id WHERE pm.month = m.month AND pm.kelompok_id = m.kelompok_id) AS average_score FROM public.lupg_phq_meetings m GROUP BY m.month, m.kelompok_id; CREATE VIEW public.lupg_intensif_summary WITH (security_invoker = true) AS SELECT date_trunc('month', a.activity_date::timestamp)::date AS month, a.kelompok_id, a.program_code, count(DISTINCT a.id)::integer AS activity_count, count(DISTINCT att.participant_id) FILTER (WHERE att.status = 'hadir')::integer AS present_participant_count FROM public.lupg_intensif_activities a LEFT JOIN public.lupg_intensif_attendance att ON att.activity_id = a.id GROUP BY date_trunc('month', a.activity_date::timestamp)::date, a.kelompok_id, a.program_code; REVOKE ALL ON TABLE public.lupg_phq_summary, public.lupg_intensif_summary FROM PUBLIC, anon; GRANT SELECT ON TABLE public.lupg_phq_summary, public.lupg_intensif_summary TO authenticated;
